			SettlementID: target.ID,
			Reason:       req.Reason,
			Account:      target.Account,
			Asset:        target.Asset,
			Amount:       target.Amount,
			Fee:          target.Fee,
			Charged:      target.Charged,
			AfterSeq:     int64(len(l.reg.state.Settlements)),
			Seq:          int64(len(l.reg.state.Refunds)) + 1,
